package com.wizzadrds.theworldremembers.stress; import com.mojang.serialization.Codec; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.resources.Identifier; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class NpcFatigueManager extends SavedData{private final Map<UUID,Integer> data=new HashMap<>();private static final Codec<NpcFatigueManager>C=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),Codec.INT).xmap(m->{var x=new NpcFatigueManager();x.data.putAll(m);return x;},x->x.data);private static final SavedDataType<NpcFatigueManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","fatigue"),NpcFatigueManager::new,C,null);public static NpcFatigueManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new NpcFatigueManager():l.getDataStorage().computeIfAbsent(TYPE);}public int value(UUID id){return data.getOrDefault(id,0);}public void increase(UUID id,int n){int old=value(id),v=Math.min(100,old+Math.max(0,n));if(v!=old){data.put(id,v);setDirty();}}public void recover(UUID id,int n){int old=value(id),v=Math.max(0,old-Math.max(0,n));if(v!=old){data.put(id,v);setDirty();}}}
